import java.util.*;
public class RocketLaunchusingforloop {

	public static void main(String[] args) {
		// TODO Auto-generated method stub
		Scanner sc= new Scanner(System.in);
		int num= sc.nextInt();
		for(int i = num;i>=1;i--) {
			System.out.println(i);
		}
		System.out.print("lift off!");
	}

}
